mapper.delete:
DELETE FROM DBF_CURRENT_TABLE_SNAPSHOT
 WHERE CURRENT_TABLE_ID IN (SELECT CT.CURRENT_TABLE_ID
                              FROM DBF_CURRENT_TABLE_SNAPSHOT CT
                             INNER JOIN DBF_COMMIT_TARGET DCT
                                ON DCT.COMMIT_LOG_ID = #{commitLogId}
                               AND DCT.DB_CONFIG_ID = #{dbConfigId}
                               AND DCT.DB_CONFIG_ID = CT.DB_CONFIG_ID
                               AND DCT.OBJECT_NAME = CT.TABLE_NAME
                               AND DCT.OBJECT_TYPE = CT.TABLE_TYPE
                             WHERE CT.DB_CONFIG_ID = #{dbConfigId}
                           )

DELETE FROM DBF_CURRENT_COLUMN_SNAPSHOT
 WHERE CURRENT_TABLE_ID IN (SELECT CT.CURRENT_TABLE_ID
                              FROM DBF_CURRENT_TABLE_SNAPSHOT CT
                             INNER JOIN DBF_COMMIT_TARGET DCT
                                ON DCT.COMMIT_LOG_ID = #{commitLogId}
                               AND DCT.DB_CONFIG_ID = #{dbConfigId}
                               AND DCT.DB_CONFIG_ID = CT.DB_CONFIG_ID
                               AND DCT.OBJECT_NAME = CT.TABLE_NAME
                               AND DCT.OBJECT_TYPE = CT.TABLE_TYPE
                             WHERE CT.DB_CONFIG_ID = #{dbConfigId}
                           );
